-- V56: the project chat's action proposals (ADR 0023, stage 1: rule-based, no LLM). A proposal is a row an operator confirms or dismisses; the
-- AI never executes. Expand only: one new table, nothing dropped or rewritten, no existing row touched.
--   1. action_code is an allow-list code of kivra-core (ChatActionCode), never free text. The label is generated by the server.
--   2. target_id and expected_version are the order the action is for and the order version it is valid at. A version that moved expires the row.
--   3. active_key is set only while PROPOSED (the same pattern as V23's active_key). UNIQUE over it means at most one open proposal per
--      (project, code, target); a finished row has a NULL key and never blocks a new proposal.
CREATE TABLE project_chat_actions (
    action_id        CHAR(26)     NOT NULL,                              -- ULID
    project_id       CHAR(26)     NOT NULL,
    action_code      VARCHAR(64)  NOT NULL,                              -- ChatActionCode name (fixed allow-list)
    target_id        CHAR(26)     NULL,                                  -- the order ID the action is for
    expected_version BIGINT       NULL,                                  -- the order's version when proposed
    state            VARCHAR(16)  NOT NULL,                              -- PROPOSED, EXECUTED, DISMISSED, EXPIRED, FAILED
    active_key       VARCHAR(192) GENERATED ALWAYS AS (
                         CASE WHEN state = 'PROPOSED' THEN CONCAT(project_id, ':', action_code, ':', COALESCE(target_id, '-')) ELSE NULL END
                     ),
    result_code      VARCHAR(64)  NULL,                                  -- fixed code, never free text
    proposed_at      DATETIME(6)  NOT NULL,
    resolved_at      DATETIME(6)  NULL,
    resolved_by      VARCHAR(255) NULL,                                  -- the operator's owner key (never the AI)
    PRIMARY KEY (action_id),
    CONSTRAINT fk_chat_action_project FOREIGN KEY (project_id) REFERENCES projects (project_id) ON DELETE CASCADE,
    CONSTRAINT uk_chat_action_active UNIQUE (active_key),
    CONSTRAINT ck_chat_action_state CHECK (state IN ('PROPOSED', 'EXECUTED', 'DISMISSED', 'EXPIRED', 'FAILED'))
);
CREATE INDEX ix_chat_action_project_state ON project_chat_actions (project_id, state);
